#include <stdlib.h>
#include <string.h>
#include <omp.h>

#ifdef __AVX512F__
#define VW 16
#define MR 12
#define NR 32
#define KC 384
#define MCP 8
#define NCP 4
#else
#define VW 8
#define MR 6
#define NR 16
#define KC 512
#define MCP 12
#define NCP 8
#endif

typedef float V __attribute__((vector_size(VW * 4)));
typedef float VU __attribute__((vector_size(VW * 4), aligned(4)));

#if MR == 12
#define FOR_ROWS(M) M(0) M(1) M(2) M(3) M(4) M(5) M(6) M(7) M(8) M(9) M(10) M(11)
#else
#define FOR_ROWS(M) M(0) M(1) M(2) M(3) M(4) M(5)
#endif

static void *amalloc(size_t bytes)
{
    size_t sz = (bytes + 63) & ~(size_t)63;
    if (sz == 0) sz = 64;
    return aligned_alloc(64, sz);
}

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int mr, int nr, int accum)
{
#define DECL(i) V c##i##0 = {0}, c##i##1 = {0};
    FOR_ROWS(DECL)
#undef DECL

    if (mr == MR && nr == NR) {
#define PF(i) __builtin_prefetch(c + (size_t)(i) * ldc, 1, 3); \
              __builtin_prefetch(c + (size_t)(i) * ldc + NR - 1, 1, 3);
        FOR_ROWS(PF)
#undef PF
    }

#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        V b0 = *(const V *)(b);
        V b1 = *(const V *)(b + VW);
        __builtin_prefetch(b + 8 * NR, 0, 3);
#define FMA(i) { V a_ = (V){0} + a[i]; c##i##0 += a_ * b0; c##i##1 += a_ * b1; }
        FOR_ROWS(FMA)
#undef FMA
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
        if (accum) {
#define ST(i) { VU *p = (VU *)(c + (size_t)(i) * ldc); p[0] += c##i##0; \
                *(VU *)(c + (size_t)(i) * ldc + VW) += c##i##1; }
            FOR_ROWS(ST)
#undef ST
        } else {
#define ST(i) { *(VU *)(c + (size_t)(i) * ldc) = c##i##0; \
                *(VU *)(c + (size_t)(i) * ldc + VW) = c##i##1; }
            FOR_ROWS(ST)
#undef ST
        }
    } else {
        float t[MR * NR] __attribute__((aligned(64)));
#define ST(i) { *(V *)(t + (i) * NR) = c##i##0; *(V *)(t + (i) * NR + VW) = c##i##1; }
        FOR_ROWS(ST)
#undef ST
        for (int i = 0; i < mr; i++)
            for (int j = 0; j < nr; j++) {
                if (accum) c[(size_t)i * ldc + j] += t[i * NR + j];
                else c[(size_t)i * ldc + j] = t[i * NR + j];
            }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    int npA = (n + MR - 1) / MR, npB = (n + NR - 1) / NR;
    size_t Mpad = (size_t)npA * MR, Npad = (size_t)npB * NR;
    int nkb = (n + KC - 1) / KC;

    float *Ap = (float *)amalloc(Mpad * n * sizeof(float));
    float *Bp = (float *)amalloc(Npad * n * sizeof(float));

    int nib = (npA + MCP - 1) / MCP;
    int njb = (npB + NCP - 1) / NCP;

    #pragma omp parallel
    {
        /* Pack A: for each k-block, row panels of MR, layout [k][r]. */
        #pragma omp for schedule(static) nowait
        for (int t = 0; t < nkb * npA; t++) {
            int kb = t / npA, p = t % npA;
            int pc = kb * KC;
            int kc = n - pc < KC ? n - pc : KC;
            float *dst = Ap + (size_t)pc * Mpad + (size_t)p * MR * kc;
            int r0 = p * MR;
            int h = n - r0 < MR ? n - r0 : MR;
            for (int r = 0; r < h; r++) {
                const float *src = A + (size_t)(r0 + r) * n + pc;
                for (int k = 0; k < kc; k++) dst[k * MR + r] = src[k];
            }
            for (int r = h; r < MR; r++)
                for (int k = 0; k < kc; k++) dst[k * MR + r] = 0.0f;
        }

        /* Pack B: for each k-block, column panels of NR, layout [k][j]. */
        #pragma omp for schedule(static)
        for (int t = 0; t < nkb * npB; t++) {
            int kb = t / npB, jp = t % npB;
            int pc = kb * KC;
            int kc = n - pc < KC ? n - pc : KC;
            float *dst = Bp + (size_t)pc * Npad + (size_t)jp * NR * kc;
            int j0 = jp * NR;
            int w = n - j0 < NR ? n - j0 : NR;
            for (int k = 0; k < kc; k++) {
                const float *src = B + (size_t)(pc + k) * n + j0;
                float *d = dst + (size_t)k * NR;
                if (w == NR) {
                    memcpy(d, src, NR * sizeof(float));
                } else {
                    int j;
                    for (j = 0; j < w; j++) d[j] = src[j];
                    for (; j < NR; j++) d[j] = 0.0f;
                }
            }
        }

        #pragma omp for collapse(2) schedule(dynamic, 1)
        for (int ib = 0; ib < nib; ib++) {
            for (int jb = 0; jb < njb; jb++) {
                int p0 = ib * MCP, p1 = p0 + MCP < npA ? p0 + MCP : npA;
                int q0 = jb * NCP, q1 = q0 + NCP < npB ? q0 + NCP : npB;
                for (int kb = 0; kb < nkb; kb++) {
                    int pc = kb * KC;
                    int kc = n - pc < KC ? n - pc : KC;
                    int accum = kb > 0;
                    const float *abase = Ap + (size_t)pc * Mpad;
                    const float *bbase = Bp + (size_t)pc * Npad;
                    for (int q = q0; q < q1; q++) {
                        int j0 = q * NR;
                        int nr = n - j0 < NR ? n - j0 : NR;
                        const float *bp = bbase + (size_t)q * NR * kc;
                        for (int p = p0; p < p1; p++) {
                            int r0 = p * MR;
                            int mr = n - r0 < MR ? n - r0 : MR;
                            kernel(kc, abase + (size_t)p * MR * kc, bp,
                                   C + (size_t)r0 * n + j0, n, mr, nr, accum);
                        }
                    }
                }
            }
        }
    }

    free(Ap);
    free(Bp);
}
